using Master.Entity.TableEntities;
using Shared.Kernel.Apps;

namespace Master.Repository.SeedData;

/// <summary>
/// The navigation tree, transcribed from the Bill-Book shell design
/// (<c>Shell.dc.html</c>) and matched against the routes the Angular app actually
/// serves.
///
/// One flat list of <see cref="Menu"/> rows: rail modules, the sections inside their
/// panels and the screens inside those sections, told apart by <c>Type</c> and
/// joined by <c>ParentId</c>.
///
/// Three things are worth knowing before editing this file.
///
/// <para><b>An item with no route is seeded inactive.</b> The design covers screens
/// that are not built yet — account types, units of measure, licences. They are
/// here with <c>RoutePath = null</c> and <c>IsActive = false</c> so the tree stays
/// complete and switching one on later is a data change rather
/// than a code change. <c>MenuService</c> filters on <c>IsActive</c>, so nothing
/// unbuilt reaches a user today.</para>
///
/// <para><b>Placement and permission are separate.</b> The design groups HSN/SAC,
/// UOM types and metal purity under Inventory, and reconciliation under Banking,
/// while those routes live under <c>/settings</c> and <c>/accounting</c> and are
/// guarded accordingly. The row sits where the design puts it; its <c>Module</c>
/// follows the route's own guard, so the menu can never offer a screen the router
/// will then refuse.</para>
///
/// <para><b>Ids are fixed and blocked by level</b> — rails 1-99, groups 100-999,
/// items from 1000. They are <c>HasData</c> seeds, so an id is part of the migration
/// history: append with new ids, never renumber.</para>
/// </summary>
public static class MenuSeed
{
    /// <summary>
    /// The rows every app's menu shows (TK-42): Home, the Settings rail, and its
    /// Organisation and Users-and-access sections with their screens. Every other
    /// row is RetailErp's. Print templates stay RetailErp's for now because each
    /// row is a RetailErp document type.
    /// </summary>
    public static readonly IReadOnlySet<int> SharedMenuIds = new HashSet<int>
    {
        1,                                              // Home
        9,                                              // Settings rail
        114, 1079, 1080, 1081, 1082, 1083, 1084, 1085,  // Organisation
        1125,                                           // Approval workflows (TK-103)
        115, 1086, 1087, 1088, 1089, 1090, 1106,        // Users and access
    };

    /// <summary>
    /// Rows that belong to a set of apps other than RetailErp or all four (TK-48):
    /// the People rail, shown by HRMS, Payroll and School, and its HRMS-only screens.
    /// </summary>
    public static readonly IReadOnlyDictionary<int, App> AppsByMenuId = new Dictionary<int, App>
    {
        [10] = App.Hrms | App.Payroll | App.School,
        [118] = App.Hrms | App.Payroll | App.School,
        [1107] = App.Hrms | App.Payroll | App.School,
        [1108] = App.Hrms | App.Payroll | App.School,
        [1109] = App.Hrms,
        [1110] = App.Hrms,

        // School (TK-60). The contact master is shared with RetailErp, for
        // guardians and maintenance vendors.
        [2] = App.RetailErp | App.School,
        [101] = App.RetailErp | App.School,
        [1001] = App.RetailErp | App.School,
        [11] = App.School,
        [12] = App.School,
        [13] = App.School,
        [119] = App.School,
        [120] = App.School,
        [121] = App.School,
        [1111] = App.School,
        [1112] = App.School,
        [1113] = App.School,
        [1114] = App.School,
        [1115] = App.School,
        [1116] = App.School,
        [1117] = App.School,
        [1118] = App.School,
        [1119] = App.School,
        [1120] = App.School,
        [1121] = App.School,
        [1122] = App.School,
        [1123] = App.School,
        [1124] = App.School,
    };

    public static IReadOnlyList<Menu> Build()
    {
        IReadOnlyList<Menu> rows = Rows();
        foreach (Menu row in rows)
        {
            row.Apps = AppsByMenuId.TryGetValue(row.MenuId, out App apps)
                ? apps
                : SharedMenuIds.Contains(row.MenuId) ? App.All : App.RetailErp;
        }

        return rows;
    }

